package com.bookstore.order.controller;
import com.bookstore.order.dto.OrderRequest; import com.bookstore.order.entity.Order; import com.bookstore.order.repository.OrderRepository; import com.bookstore.order.service.OrderService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderService service; private final OrderRepository repo; public OrderController(OrderService service,OrderRepository repo){this.service=service;this.repo=repo;} @GetMapping public List<Order> all(){return repo.findAll();} @PostMapping public Order create(@Valid @RequestBody OrderRequest r){return service.create(r);} }
